    lines = [
        f"File: {chunk.file_path}",
        f"Language: {chunk.language}",
        f"Type: {chunk.chunk_type}"
    ]

    if chunk.parent_symbol:
        lines.append(f"Parent: {chunk.parent_symbol}")
